//! Structured TypeScript model generation.
//!
//! The structured target keeps model and operation type files separate so SDK
//! packages remain easy to navigate as an OpenAPI contract grows.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write;

use anyhow::Result;
use serde_json::Value;

use poolster_core::GeneratedFile;
use poolster_core::ast::{AdditionalProperties, Api, Operation, SchemaKind, SchemaValue};

const NOTICE: &str =
    "/**\n * Generated by Poolster.\n * Do not edit manually.\n * Source: text content\n */\n\n";
const NOTICE_WITHOUT_SOURCE: &str =
    "/**\n * Generated by Poolster.\n * Do not edit manually.\n */\n\n";

/// Emits TypeScript model and operation type files for the structured SDK
/// target.
#[derive(Default)]
pub(crate) struct ModelRenderer;

#[derive(Clone)]
pub(crate) struct ModelRenderOptions {
    pub output_dir: String,
    pub schema_output_dir: Option<String>,
    pub operation_output_dir: Option<String>,
    pub group_by_tag: bool,
    pub model: ModelOptions,
}

mod assembly;

/// Typed schema formatting and transformation choices for generated models.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelOptions {
    pub array_type: ArrayType,
    pub optional_type: OptionalType,
    pub syntax: Syntax,
    pub enum_type: EnumType,
    pub enum_key_casing: EnumKeyCasing,
    pub enum_const_casing: EnumConstCasing,
    pub enum_type_suffix: String,
    pub integer_as_string: bool,
    pub int64_type: Int64Type,
    pub remove_optional_properties: bool,
    /// Accept future scalar enum wire values while preserving known members.
    pub open_enums: bool,
}

impl Default for ModelOptions {
    fn default() -> Self {
        Self {
            array_type: ArrayType::Array,
            optional_type: OptionalType::QuestionToken,
            syntax: Syntax::Type,
            enum_type: EnumType::Literal,
            enum_key_casing: EnumKeyCasing::None,
            enum_const_casing: EnumConstCasing::CamelCase,
            enum_type_suffix: "Key".into(),
            integer_as_string: false,
            int64_type: Int64Type::Number,
            remove_optional_properties: false,
            open_enums: false,
        }
    }
}

/// Representation of OpenAPI integer schemas with format `int64`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Int64Type {
    #[default]
    Number,
    String,
    BigInt,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArrayType {
    /// Poolster's default `array` setting, e.g. `string[]`.
    Array,
    /// Poolster's `generic` setting, e.g. `Array<string>`.
    Generic,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OptionalType {
    /// Poolster's default: `name?: T`.
    QuestionToken,
    /// Poolster's `questionTokenAndUndefined`: `name?: T | undefined`.
    QuestionTokenAndUndefined,
    /// Poolster's `undefined`: `name: T | undefined`.
    Undefined,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Syntax {
    Type,
    Interface,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EnumType {
    Literal,
    AsConst,
    Enum,
    ConstEnum,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EnumKeyCasing {
    None,
    CamelCase,
    PascalCase,
    SnakeCase,
    ScreamingSnakeCase,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EnumConstCasing {
    CamelCase,
    PascalCase,
}

fn generated_notice(api: &Api) -> String {
    match api.annotations.get("source").and_then(Value::as_str) {
        Some("") => NOTICE_WITHOUT_SOURCE.into(),
        Some(source) => format!(
            "/**\n * Generated by Poolster.\n * Do not edit manually.\n * Source: {source}\n */\n\n"
        ),
        None => NOTICE.into(),
    }
}

